import React from "react";
import { Container } from "react-bootstrap";
import { Header, ExperienceCard } from "../../components";
import usePortfolioData from "../../hooks/usePortfolioData";
import styles from "./Involvements.module.css";

// @@ AI-COMMENT: Involvements page component with warm neutral grid design
const Involvements = () => {
  const { involvements: involvementsData, loading } = usePortfolioData();

  if (loading) return null;

  return (
    <React.Fragment>
      <Header title="Involvements" />
      <Container fluid className={styles.container}>
        <div className={styles.involvementsGrid}>
          {involvementsData.map((obj, index) => (
            <div key={index} className={styles.involvementItem}>
              <ExperienceCard
                title={obj.title}
                organization={obj.organization}
                liveUrl={obj.liveUrl}
                duration={obj.duration}
                description={obj.description}
                logo={obj.logo}
                techStack={obj.techStack}
                variant="success"
              />
            </div>
          ))}
        </div>
      </Container>
    </React.Fragment>
  );
};

export default Involvements;
